def is_simple_power(x: int, n: int) -> bool:
    if x == 1:
        return True
    if n == 1:
        return x == 1
    if x <= 0 or n <= 0:
        return False
    current = n
    while current < x:
        if current > x // n:
            return False
        current *= n
    return current == x

def iscube(a: int) -> bool:
    if a == 0:
        return True
    if a < 0:
        return iscube(-a)
    lo = 1
    hi = a
    while lo <= hi:
        mid = (lo + hi) // 2
        cube = mid * mid * mid
        if cube == a:
            return True
        elif cube < a:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

